package output

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// ImportBlocksFile is the generated file's name, relative to the repo root.
const ImportBlocksFile = "imports.tf"

// WriteImportBlocks appends one config-driven `import` block for every entry that still needs one,
// and returns how many it wrote. Zero is not an error — a run that only refreshed already-managed
// datasets legitimately has nothing new to import.
//
// Importing through config rather than a script puts the adoption in the same pull request as the
// resources, so a reviewer sees `terraform plan` account for it before anything touches state.
//
// The file goes in the repo root because that is the only place terraform accepts an import block —
// one in a child module fails with "Import blocks are only allowed in the root module" — so the
// blocks cannot sit beside the resources they import. Each block names its target through the
// module: `to = module.<name>.observe_dataset.<name>`.
//
// This repo runs the tool once per dataset id, indefinitely, so the file accumulates across runs
// rather than being written once for a fixed batch. New blocks are appended; nothing already in the
// file is parsed or rewritten. That is deliberately simple rather than deduplicating against what is
// already there: a dataset id only ever reaches this function's "needs an import" path (Entry.
// NeedsDatasetImport / NeedsGrantsImport) when nothing already declares it, and nothing can declare a
// resource this function would target without also having been through the same path — so a genuine
// duplicate block can't arise from calling this repeatedly.
//
// gate is an HCL boolean expression that is true only in the workspace pointing at the tenant the
// ids came from, e.g. `local.in_west`. It matters whenever one root config serves more than one
// tenant: an ungated block runs in every workspace, and importing a source-tenant id into a replica
// leaves state claiming to manage a dataset that does not exist there. Gating costs a version floor,
// since `for_each` in an import block needs Terraform 1.7; ungated blocks work on 1.5. It is only
// used for a newly-created file's header comment — an existing file keeps whatever wording it was
// first written with.
func WriteImportBlocks(path string, m *Manifest, gate string) (int, error) {
	var b strings.Builder
	count := 0
	for _, e := range m.Entries {
		if e.NeedsDatasetImport() {
			writeImportBlock(&b, e.ImportAddress, e.SourceDatasetID, gate)
			count++
		}
		// observe_resource_grants is keyed by the dataset's OID and automatically manages the complete
		// grant set. Its import id is the OID string, not the bare numeric id.
		if e.NeedsGrantsImport() {
			grantsAddress := m.ModuleAddress + ".observe_resource_grants." + e.ResourceName
			grantsID := "o:::dataset:" + e.SourceDatasetID
			writeImportBlock(&b, grantsAddress, grantsID, gate)
			count++
		}
	}
	if count == 0 {
		return 0, nil
	}

	existing, err := os.ReadFile(path)
	switch {
	case err == nil:
		out := append(existing, []byte(b.String())...)
		return count, os.WriteFile(path, out, 0o644)
	case os.IsNotExist(err):
		var full strings.Builder
		full.WriteString(importBlocksHeader(gate, m.CustomerID))
		full.WriteString(b.String())
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
			return 0, err
		}
		return count, os.WriteFile(path, []byte(full.String()), 0o644)
	default:
		return 0, err
	}
}

// importBlocksHeader is written only once, when the file is first created.
func importBlocksHeader(gate, customerID string) string {
	var b strings.Builder
	b.WriteString("# Generated by tf-dataset-import. Not hand-maintained.\n")
	b.WriteString("#\n")
	b.WriteString("# Each block adopts one existing Observe dataset (and, if it has any, its RBAC grants) into\n")
	b.WriteString("# this repo's state. `terraform apply` performs the imports; the following `terraform plan`\n")
	b.WriteString("# should report no changes. New blocks are appended here as this tool is run for more\n")
	b.WriteString("# dataset ids over time — nothing above a given point is ever rewritten.\n")
	b.WriteString("#\n")
	b.WriteString("# A block whose resource is already in state is a no-op, so there's no need to remove one\n")
	b.WriteString("# once the import lands — it just stops describing anything that still needs doing.\n")
	b.WriteString("#\n")

	if gate != "" {
		fmt.Fprintf(&b, "# The blocks are gated on `%s`, which must be true only in the workspace holding\n", gate)
		fmt.Fprintf(&b, "# customer %s. Ungated, they would also run in every other workspace sharing this config\n", customerID)
		b.WriteString("# and import ids that do not exist there. This needs Terraform 1.7 or newer, which is where\n")
		b.WriteString("# an import block gained for_each.\n")
	} else {
		b.WriteString("# These blocks are ungated, so every workspace sharing this config runs them. That is correct\n")
		fmt.Fprintf(&b, "# only if the config is applied to customer %s alone; against a second tenant the import\n", customerID)
		b.WriteString("# fails on ids that do not exist there. Pass -import-gate to scope them to one workspace.\n")
	}
	return b.String()
}

func writeImportBlock(b *strings.Builder, address, id, gate string) {
	b.WriteString("\nimport {\n")
	if gate != "" {
		fmt.Fprintf(b, "  for_each = %s ? toset([%q]) : toset([])\n", gate, id)
		fmt.Fprintf(b, "  to       = %s\n", address)
		b.WriteString("  id       = each.value\n")
	} else {
		fmt.Fprintf(b, "  to = %s\n", address)
		fmt.Fprintf(b, "  id = %q\n", id)
	}
	b.WriteString("}\n")
}
